INSERT INTO "public"."chatbot_intents" ("id", "tenant_id", "intent_name", "description", "training_phrases", "responses", "entities", "context_required", "context_output", "actions", "confidence_threshold", "is_active", "priority", "matched_count", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('58666dd0-fc91-475b-b4d2-8be9610f5851', 'd563b428-b1a9-4bf3-af62-a175e92e8e18', 'agradecimiento', 'Respuestas cuando el cliente agradece', '["gracias por la ayuda", "te agradezco", "muy amable", "excelente atención", "muchas gracias por la información", "perfecto gracias", "genial gracias", "ok gracias", "agradecido", "gracias por responder"]', '["¡Con gusto! 😊 Estamos para ayudarte cuando lo necesites.", "Gracias a ti por comunicarte con {{business_name}}.", "Ha sido un placer ayudarte. ¡Que tengas un excelente día! 👋"]', NULL, NULL, NULL, NULL, 0.65, TRUE, 11, 2, '2026-07-30T06:35:18.602653', '2026-08-03T05:44:06.762695', NULL, NULL, 2, NULL, NULL, FALSE);
