INSERT INTO "public"."chatbot_intents" ("id", "tenant_id", "intent_name", "description", "training_phrases", "responses", "entities", "context_required", "context_output", "actions", "confidence_threshold", "is_active", "priority", "matched_count", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('abe437c7-6829-4d8a-81df-c7d966ce8399', '362d91bd-e514-43f1-ae12-9e44f9ca440b', 'contactar_asesor', 'Solicitud de contacto con un agente humano', '["agente","asesor","hablar con alguien","persona","operador","atención al cliente","ejecutivo","representante","transferir"]', '["Por supuesto, te conectamos con un asesor en este momento. Por favor, espera un instante.","Claro, un asesor se comunicará contigo a la brevedad. Gracias por tu paciencia.","Entiendo, en un momento te atenderá un agente. Por favor, mantente en línea."]', NULL, NULL, NULL, NULL, 0.7, TRUE, 5, 0, '2026-08-04T15:01:12.320575', '2026-08-04T15:01:12.320575', NULL, NULL, 0, NULL, NULL, FALSE);
INSERT INTO "public"."chatbot_intents" ("id", "tenant_id", "intent_name", "description", "training_phrases", "responses", "entities", "context_required", "context_output", "actions", "confidence_threshold", "is_active", "priority", "matched_count", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('eb092cc5-2a8b-4bb1-bd2a-8410229df1bc', '362d91bd-e514-43f1-ae12-9e44f9ca440b', 'consulta_envio', 'Consultas sobre envíos y entregas', '["envío","delivery","despacho","entrega","cuándo llega","tiempo de entrega","demora","seguimiento de pedido","rastrear"]', '["El tiempo de entrega estimado es de 2 a 5 días hábiles dentro de Lima y de 5 a 7 días hábiles para provincias. ¿Te gustaría rastrear tu pedido?","Realizamos envíos a todo el Perú. El costo y tiempo de entrega varían según tu ubicación. ¿Podrías indicarme tu distrito o ciudad para darte mayor precisión?"]', NULL, NULL, NULL, NULL, 0.7, TRUE, 6, 0, '2026-08-04T15:01:12.320575', '2026-08-04T15:01:12.320575', NULL, NULL, 0, NULL, NULL, FALSE);
INSERT INTO "public"."chatbot_intents" ("id", "tenant_id", "intent_name", "description", "training_phrases", "responses", "entities", "context_required", "context_output", "actions", "confidence_threshold", "is_active", "priority", "matched_count", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('01202f22-1b07-4a2c-b089-f3718a55a60e', '362d91bd-e514-43f1-ae12-9e44f9ca440b', 'forma_pago', 'Consultas sobre métodos de pago', '["pago","pagar","tarjeta","transferencia","yape","plin","efectivo","depósito","métodos de pago"]', '["Aceptamos pagos con tarjeta de crédito/débito, transferencia bancaria, Yape y Plin. ¿Cuál es tu método de pago preferido?","Puedes pagar con tarjeta (Visa, Mastercard), transferencia bancaria, Yape o Plin. ¿Cuál te resulta más conveniente?"]', NULL, NULL, NULL, NULL, 0.7, TRUE, 7, 0, '2026-08-04T15:01:12.320575', '2026-08-04T15:01:12.320575', NULL, NULL, 0, NULL, NULL, FALSE);
INSERT INTO "public"."chatbot_intents" ("id", "tenant_id", "intent_name", "description", "training_phrases", "responses", "entities", "context_required", "context_output", "actions", "confidence_threshold", "is_active", "priority", "matched_count", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('c0b220fe-018a-4b95-a11a-c678b21dff4a', '362d91bd-e514-43f1-ae12-9e44f9ca440b', 'queja_reclamo', 'Atención de quejas o reclamos', '["queja","reclamo","problema","insatisfecho","error","mal servicio","devolución","me quejo"]', '["Lamento mucho el inconveniente. Permíteme revisar tu caso para darte una solución rápida. ¿Podrías contarme un poco más sobre lo sucedido?","Agradecemos tu feedback, ya que nos ayuda a mejorar. Un asesor especializado revisará tu caso y te contactará a la brevedad.","Lamento el problema que has experimentado. Déjame tus datos y un supervisor se comunicará contigo en los próximos minutos para resolverlo."]', NULL, NULL, NULL, NULL, 0.7, TRUE, 8, 0, '2026-08-04T15:01:12.320575', '2026-08-04T15:01:12.320575', NULL, NULL, 0, NULL, NULL, FALSE);
INSERT INTO "public"."chatbot_intents" ("id", "tenant_id", "intent_name", "description", "training_phrases", "responses", "entities", "context_required", "context_output", "actions", "confidence_threshold", "is_active", "priority", "matched_count", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('48212366-fb73-45e2-9f6c-098051475946', '362d91bd-e514-43f1-ae12-9e44f9ca440b', 'informacion_empresa', 'Solicitud de información general de la empresa', '["quiénes son","empresa","acerca de","información","quién es","sobre ustedes","qué hacen"]', '["Somos una empresa comprometida con brindar el mejor servicio a nuestros clientes. ¿Hay algo específico que te gustaría saber sobre nosotros? Con gusto te informamos.","Con gusto te brindamos información sobre nuestra empresa. ¿Hay algo en particular que te gustaría conocer?"]', NULL, NULL, NULL, NULL, 0.7, TRUE, 9, 0, '2026-08-04T15:01:12.320575', '2026-08-04T15:01:12.320575', NULL, NULL, 0, NULL, NULL, FALSE);
INSERT INTO "public"."chatbot_intents" ("id", "tenant_id", "intent_name", "description", "training_phrases", "responses", "entities", "context_required", "context_output", "actions", "confidence_threshold", "is_active", "priority", "matched_count", "created_at", "updated_at", "created_by", "updated_by", "version", "deleted_at", "deleted_by", "is_deleted") VALUES ('4ee0449f-36c3-4fba-87ad-4cb0ba132909', '362d91bd-e514-43f1-ae12-9e44f9ca440b', 'despedida', 'Despedidas cordiales', '["gracias","adiós","chau","hasta luego","nos vemos","que tengas buen día","muchas gracias","gracias por tu atención"]', '["Gracias a ti por contactarnos. ¡Que tengas un excelente día! Si necesitas algo más, aquí estamos.","Ha sido un placer atenderte. No dudes en escribirnos si requieres algo más. ¡Hasta pronto!","¡Gracias por comunicarte! Quedo atento por si surge cualquier otra consulta. Que tengas un maravilloso día."]', NULL, NULL, NULL, NULL, 0.7, TRUE, 10, 0, '2026-08-04T15:01:12.320575', '2026-08-04T15:01:12.320575', NULL, NULL, 0, NULL, NULL, FALSE);

-- ============================================
-- Tabla: contacts
-- ============================================

CREATE TABLE IF NOT EXISTS "public"."contacts" (
    "id" UUID DEFAULT gen_random_uuid() NOT NULL,
    "tenant_id" UUID NOT NULL,
    "first_name" VARCHAR(100),
    "last_name" VARCHAR(100),
    "full_name" VARCHAR(200),
    "email" VARCHAR(255),
    "phone" VARCHAR(50),
    "whatsapp_phone" VARCHAR(50),
    "company" VARCHAR(200),
    "job_title" VARCHAR(100),
    "avatar_url" VARCHAR(500),
    "status" VARCHAR(20) DEFAULT 'ACTIVE'::character varying NOT NULL,
    "language" VARCHAR(5) DEFAULT 'es'::character varying,
    "timezone" VARCHAR(50) DEFAULT 'UTC'::character varying,
    "tags" VARCHAR(500),
    "custom_fields" TEXT,
    "notes" TEXT,
    "last_contacted_at" TIMESTAMP,
    "conversation_count" INTEGER DEFAULT 0 NOT NULL,
    "message_count" INTEGER DEFAULT 0 NOT NULL,
    "is_subscribed" BOOLEAN DEFAULT true NOT NULL,
    "unsubscribed_at" TIMESTAMP,
    "blocked_at" TIMESTAMP,
    "blocked_reason" VARCHAR(500),
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_by" UUID,
    "updated_by" UUID,
    "version" BIGINT DEFAULT 0 NOT NULL,
    "deleted_at" TIMESTAMP,
    "deleted_by" UUID,
    "is_deleted" BOOLEAN DEFAULT false NOT NULL,
    "normalized_phone" VARCHAR(20),
    "document_type" VARCHAR(20),
    "document_number" VARCHAR(11),
    "address" VARCHAR(255)
);

