-- ============================================
-- Tabla: conversation_messages
-- ============================================

CREATE TABLE IF NOT EXISTS "public"."conversation_messages" (
    "id" UUID DEFAULT gen_random_uuid() NOT NULL,
    "tenant_id" UUID NOT NULL,
    "conversation_id" UUID NOT NULL,
    "user_id" UUID,
    "direction" VARCHAR(10) NOT NULL,
    "type" VARCHAR(20) DEFAULT 'TEXT'::character varying NOT NULL,
    "status" VARCHAR(20) DEFAULT 'SENT'::character varying NOT NULL,
    "content" TEXT,
    "channel_message_id" VARCHAR(255),
    "reply_to_message_id" VARCHAR(255),
    "sender_name" VARCHAR(255),
    "sender_phone" VARCHAR(50),
    "sender_email" VARCHAR(255),
    "is_from_bot" BOOLEAN DEFAULT false NOT NULL,
    "bot_intent" VARCHAR(100),
    "bot_confidence" REAL,
    "sent_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "delivered_at" TIMESTAMP,
    "read_at" TIMESTAMP,
    "failed_at" TIMESTAMP,
    "failure_reason" VARCHAR(500),
    "metadata" TEXT,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_by" UUID,
    "updated_by" UUID,
    "version" BIGINT DEFAULT 0 NOT NULL,
    "sender_type" VARCHAR(10) DEFAULT 'CUSTOMER'::character varying NOT NULL,
    "ai_processed" BOOLEAN DEFAULT false NOT NULL
);

