-- ============================================
-- Tabla: knowledge_base
-- ============================================

CREATE TABLE IF NOT EXISTS "public"."knowledge_base" (
    "id" UUID NOT NULL,
    "tenant_id" UUID NOT NULL,
    "title" VARCHAR(500) NOT NULL,
    "content" TEXT NOT NULL,
    "source_type" VARCHAR(20) DEFAULT 'manual'::character varying NOT NULL,
    "source_url" VARCHAR(1000),
    "file_url" VARCHAR(500),
    "tags" VARCHAR(500),
    "is_deleted" BOOLEAN DEFAULT false NOT NULL,
    "deleted_at" TIMESTAMP,
    "deleted_by" UUID,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_by" UUID,
    "updated_by" UUID,
    "version" BIGINT DEFAULT 0 NOT NULL,
    "extracted_text" TEXT
);

INSERT INTO "public"."knowledge_base" ("id", "tenant_id", "title", "content", "source_type", "source_url", "file_url", "tags", "is_deleted", "deleted_at", "deleted_by", "created_at", "updated_at", "created_by", "updated_by", "version", "extracted_text") VALUES ('19862fbf-8682-4b07-85fb-607cf6d62d93', 'd563b428-b1a9-4bf3-af62-a175e92e8e18', 'Sitio web de la empresa el iqueño - implementos agricolas', 'Nuestra Historia
FSI Implementos Agrícolas es una empresa peruana especializada en la fabricación de cosechadoras de papa, picadoras agrícolas, desbrozadoras e implementos para el campo. Nacemos como respuesta a la necesidad de todos los agricultores y empresas agroindustriales del país en hacer más fácil la tarea del agricultor y realizarlo en menos tiempo. Más de 30 años de experiencia fabricando cosechadoras, picadoras, maquinaria e implementos agrícolas para el campo peruano a los mejores precios. F.S.I SAC, desarrolla, innova, fabrica cosechadoras, picadoras, desbrozadoras y maquinaria agrícola para tractor en Perú.

Nuestra Misión
Proporcionar implementos agrícolas de la más alta calidad que mejoren la eficiencia y productividad de nuestros clientes, contribuyendo al desarrollo del sector agrícola.', 'url', 'https://eliquenoimplementosagricolas.com/', NULL, 'productos, repuestos, historia, asesor', FALSE, NULL, NULL, '2026-07-28T08:21:03.621369', '2026-07-28T08:21:03.621369', '95e009fb-66e9-437c-9d35-be4df58d425f', '95e009fb-66e9-437c-9d35-be4df58d425f', 0, NULL);
