-- ============================================
-- Tabla: orchestrator_audit_logs
-- ============================================

CREATE TABLE IF NOT EXISTS "public"."orchestrator_audit_logs" (
    "id" UUID DEFAULT gen_random_uuid() NOT NULL,
    "tenant_id" UUID NOT NULL,
    "message_id" VARCHAR(255),
    "conversation_id" VARCHAR(255),
    "contact_id" VARCHAR(255),
    "channel" VARCHAR(20) NOT NULL,
    "event_type" VARCHAR(50) NOT NULL,
    "action_type" VARCHAR(50),
    "decision_strategy" VARCHAR(100),
    "processing_time_ms" BIGINT NOT NULL,
    "status" VARCHAR(20) NOT NULL,
    "error_message" TEXT,
    "error_type" VARCHAR(100),
    "input_data" TEXT,
    "output_data" TEXT,
    "metadata" TEXT,
    "user_agent" VARCHAR(500),
    "ip_address" VARCHAR(45),
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_by" UUID,
    "updated_by" UUID,
    "version" BIGINT DEFAULT 0 NOT NULL
);


-- ============================================
-- Tabla: plans
-- ============================================

CREATE TABLE IF NOT EXISTS "public"."plans" (
    "id" UUID DEFAULT gen_random_uuid() NOT NULL,
    "name" VARCHAR(100) NOT NULL,
    "code" VARCHAR(50) NOT NULL,
    "description" VARCHAR(500),
    "monthly_price" NUMERIC(10,2) DEFAULT 0 NOT NULL,
    "yearly_price" NUMERIC(10,2) DEFAULT 0 NOT NULL,
    "max_users" INTEGER,
    "max_conversations" INTEGER,
    "max_contacts" INTEGER,
    "max_storage_mb" INTEGER,
    "features" TEXT,
    "is_active" BOOLEAN DEFAULT true NOT NULL,
    "is_public" BOOLEAN DEFAULT false NOT NULL,
    "sort_order" INTEGER DEFAULT 0 NOT NULL,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_by" UUID,
    "updated_by" UUID,
    "version" BIGINT DEFAULT 0 NOT NULL,
    "deleted_at" TIMESTAMP,
    "deleted_by" UUID,
    "is_deleted" BOOLEAN DEFAULT false NOT NULL,
    "tenant_id" UUID DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL
);

