-- ============================================
-- Tabla: quote_history
-- ============================================

CREATE TABLE IF NOT EXISTS "public"."quote_history" (
    "id" UUID DEFAULT gen_random_uuid() NOT NULL,
    "tenant_id" UUID NOT NULL,
    "quote_id" UUID NOT NULL,
    "action" VARCHAR(30) NOT NULL,
    "performed_by" UUID,
    "actor_name" VARCHAR(100),
    "channel" VARCHAR(20),
    "channel_message_id" VARCHAR(100),
    "details" VARCHAR(1000),
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_by" UUID,
    "updated_by" UUID,
    "version" BIGINT DEFAULT 0 NOT NULL
);


-- ============================================
-- Tabla: quotes
-- ============================================

CREATE TABLE IF NOT EXISTS "public"."quotes" (
    "id" UUID DEFAULT gen_random_uuid() NOT NULL,
    "tenant_id" UUID NOT NULL,
    "contact_id" UUID NOT NULL,
    "conversation_id" UUID,
    "quote_number" VARCHAR(30) NOT NULL,
    "items" TEXT NOT NULL,
    "subtotal" NUMERIC(12,2) DEFAULT 0 NOT NULL,
    "igv" NUMERIC(12,2) DEFAULT 0 NOT NULL,
    "total" NUMERIC(12,2) DEFAULT 0 NOT NULL,
    "currency" VARCHAR(5) DEFAULT 'PEN'::character varying NOT NULL,
    "status" VARCHAR(20) DEFAULT 'SENT'::character varying NOT NULL,
    "pdf_url" VARCHAR(1000),
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_by" UUID,
    "updated_by" UUID,
    "version" BIGINT DEFAULT 0 NOT NULL,
    "deleted_at" TIMESTAMP,
    "deleted_by" UUID,
    "is_deleted" BOOLEAN DEFAULT false NOT NULL,
    "discount" NUMERIC(12,2) DEFAULT 0 NOT NULL,
    "observations" TEXT,
    "file_name" VARCHAR(255),
    "file_size" BIGINT,
    "file_hash" VARCHAR(128),
    "storage_key" VARCHAR(500),
    "last_resent_at" TIMESTAMP,
    "resend_count" INTEGER DEFAULT 0 NOT NULL
);


-- ============================================
-- Tabla: refresh_tokens
-- ============================================

CREATE TABLE IF NOT EXISTS "public"."refresh_tokens" (
    "id" UUID DEFAULT gen_random_uuid() NOT NULL,
    "tenant_id" UUID NOT NULL,
    "user_id" UUID NOT NULL,
    "token" VARCHAR(255) NOT NULL,
    "expires_at" TIMESTAMP NOT NULL,
    "revoked" BOOLEAN DEFAULT false NOT NULL,
    "revoked_at" TIMESTAMP,
    "device_info" VARCHAR(500),
    "ip_address" VARCHAR(45),
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_by" UUID,
    "updated_by" UUID,
    "version" BIGINT DEFAULT 0 NOT NULL
);

