-- ============================================
-- Tabla: tenants
-- ============================================

CREATE TABLE IF NOT EXISTS "public"."tenants" (
    "id" UUID DEFAULT gen_random_uuid() NOT NULL,
    "tenant_id" UUID NOT NULL,
    "company_name" VARCHAR(200) NOT NULL,
    "subdomain" VARCHAR(50) NOT NULL,
    "contact_email" VARCHAR(255) NOT NULL,
    "contact_phone" VARCHAR(20),
    "website_url" VARCHAR(500),
    "logo_url" VARCHAR(500),
    "address" VARCHAR(500),
    "city" VARCHAR(100),
    "country" VARCHAR(100),
    "timezone" VARCHAR(50) DEFAULT 'UTC'::character varying,
    "currency" VARCHAR(5) DEFAULT 'USD'::character varying,
    "status" VARCHAR(20) DEFAULT 'TRIAL'::character varying NOT NULL,
    "subscription_plan" VARCHAR(50),
    "subscription_expires_at" DATE,
    "max_users" INTEGER,
    "max_conversations" INTEGER,
    "features" TEXT,
    "created_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,
    "created_by" UUID,
    "updated_by" UUID,
    "version" BIGINT DEFAULT 0 NOT NULL,
    "deleted_at" TIMESTAMP,
    "deleted_by" UUID,
    "is_deleted" BOOLEAN DEFAULT false NOT NULL,
    "plan_id" UUID,
    "business_name" VARCHAR(200),
    "ruc" VARCHAR(20),
    "primary_color" VARCHAR(7) DEFAULT '#6366f1'::character varying,
    "secondary_color" VARCHAR(7) DEFAULT '#818cf8'::character varying,
    "language" VARCHAR(10) DEFAULT 'es'::character varying,
    "locale" VARCHAR(10) DEFAULT 'es-PE'::character varying,
    "max_agents" INTEGER,
    "max_supervisors" INTEGER
);

